return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ur','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-02T07:33:51+00:00','po-revision-date'=>'2026-09-02T07:33:51+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'WordPress کے لیے ایک مکمل کیشنگ اور آپٹیمائزیشن انجن: فل پیج کیش، آبجیکٹ کیش، ڈیٹا بیس کلین اپ اور CSS/JS آپٹیمائزیشن۔ اسے اس وقت انسٹال کریں جب آپ کا ہوسٹ اپنی طرف سے کیش لیئر فراہم نہ کرتا ہو — Zinn Digital® ہوسٹنگ پر اس کی بجائے Zinn® Cache انسٹال کریں۔ فل پیج کیشنگ کے لیے LSCache ماڈیول کے ساتھ LiteSpeed یا OpenLiteSpeed سرور درکار ہے۔ LiteSpeed Cache پلگ ان کا ایک GPLv3 فورک۔','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d گھنٹے','%d hour'=>'%d گھنٹہ','%d minutes'=>'%d منٹ','%d minute'=>'%d منٹ','Purged All!'=>'سب کو صاف کر دیا گیا!','Purged the blog!'=>'بلاگ صاف کر دیا گیا!','Purged the URL!'=>'URL صاف کر دیا گیا!','Purged!'=>'صاف کر دیا گیا!','Failed to upgrade.'=>'اپ گریڈ کرنے میں ناکامی۔','Upgraded successfully.'=>'کامیابی کے ساتھ اپ گریڈ ہو گیا۔','Dashboard'=>'ڈیش بورڈ','OptimaX'=>'آپٹیمیکس','Presets'=>'پری سیٹس','General'=>'جنرل','Cache'=>'کیش','CDN'=>'سی ڈی این','Image Optimization'=>'تصویر کی اصلاح','Page Optimization'=>'صفحے کی اصلاح','Database'=>'ڈیٹا بیس','Crawler'=>'کرالر','Toolbox'=>'ٹول باکس','Cookie Name'=>'کوکی کا نام